#!/usr/bin/env python3
import requests
import json
import sys
import os

def main():
    if len(sys.argv) < 2:
        print(json.dumps({"success": False, "error": "No JSON parameters provided."}))
        sys.exit(1)

    try:
        params = json.loads(sys.argv[1])
    except json.JSONDecodeError as e:
        print(json.dumps({"success": False, "error": f"Invalid JSON parameters: {e}"}))
        sys.exit(1)

    operation = params.get('operation')
    # Allow overriding server_url via environment variable as a fallback
    server_url = params.get('server_url', os.environ.get('CADENCE_SERVER_URL', 'http://localhost:8000')).rstrip('/')
    workflow_name = params.get('workflow_name')
    inputs = params.get('inputs', {})
    run_id = params.get('run_id')

    endpoint = ""
    method = "GET"
    payload = None

    try:
        if operation == 'list_workflows':
            endpoint = '/api/v1/workflows'
        elif operation == 'get_workflow':
            if not workflow_name:
                raise ValueError("'workflow_name' is required for the 'get_workflow' operation.")
            endpoint = f'/api/v1/workflows/{workflow_name}'
        elif operation == 'trigger':
            if not workflow_name:
                raise ValueError("'workflow_name' is required for the 'trigger' operation.")
            endpoint = f'/api/v1/workflows/{workflow_name}/trigger'
            method = "POST"
            payload = inputs
        elif operation == 'get_runs':
            endpoint = '/api/v1/runs'
        elif operation == 'get_run_details':
            if not run_id:
                raise ValueError("'run_id' is required for the 'get_run_details' operation.")
            endpoint = f'/api/v1/runs/{run_id}'
        else:
            raise ValueError(f"Invalid operation: '{operation}'. Valid operations are: trigger, list_workflows, get_workflow, get_runs, get_run_details")

        full_url = f"{server_url}{endpoint}"
        headers = {'Content-Type': 'application/json', 'Accept': 'application/json'}

        response = requests.request(method, full_url, json=payload, headers=headers, timeout=45)

        # Check for non-JSON error responses first
        if response.status_code >= 400:
            error_content = response.text
            try:
                # Try to parse as JSON for a structured error message
                error_json = response.json()
                error_content = error_json.get('detail', error_content)
            except json.JSONDecodeError:
                pass # Use raw text if not JSON
            raise requests.exceptions.HTTPError(f"HTTP {response.status_code}: {error_content}", response=response)

        print(json.dumps({"success": True, "result": response.json()}))

    except requests.exceptions.RequestException as e:
        print(json.dumps({"success": False, "error": f"API request to '{server_url}' failed: {e}"}))
    except ValueError as e:
        print(json.dumps({"success": False, "error": str(e)}))
    except Exception as e:
        print(json.dumps({"success": False, "error": f"An unexpected error occurred: {e}"}))

if __name__ == "__main__":
    main()
